using System.Text;
using System.Text.Json;
using Dapper;
using Npgsql;
using Sigov.Application.Compras;
using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Compras;

public sealed class ComprasService(NpgsqlConnectionFactory factory,Microsoft.Extensions.Logging.ILogger<ComprasService> log):IComprasService
{
 public async Task<ComprasDashboard> DashboardAsync(long t,long e,CancellationToken ct){await using var c=factory.CreateConnection();var r=await c.QuerySingleAsync<R>(new CommandDefinition("select (select count(*) from sigov.compras_solicitacao where tenant_id=@T and entidade_id=@E and status in('ENVIADA','EM_ANALISE','APROVADA')) Sol,(select count(*) from sigov.compras_processo p where p.tenant_id=@T and p.entidade_id=@E and p.status not in('CONTRATADO','CANCELADO','FRACASSADO','DESERTO') and exists(select 1 from sigov.compras_processo_item i where i.processo_id=p.id and (select count(*) from sigov.compras_cotacao q where q.processo_item_id=i.id and q.status<>'DESCLASSIFICADA')<3)) Sem,(select count(*) from sigov.compras_contrato where tenant_id=@T and entidade_id=@E and status='VIGENTE' and data_fim between current_date and current_date+30) Contr,(select count(*) from sigov.compras_ata_registro_preco where tenant_id=@T and entidade_id=@E and status='VIGENTE' and data_fim between current_date and current_date+30) Atas,(select coalesce(sum(valor_estimado),0) from sigov.compras_processo where tenant_id=@T and entidade_id=@E and status not in('CONTRATADO','CANCELADO','FRACASSADO','DESERTO')) Valor",new{T=t,E=e},cancellationToken:ct));var ps=(await c.QueryAsync<CompraLinhaDto>(new CommandDefinition("select id,numero,objeto Descricao,status,null Fornecedor,valor_estimado Valor,data_abertura Inicio,data_limite Fim from sigov.compras_processo where tenant_id=@T and entidade_id=@E order by updated_at desc limit 8",new{T=t,E=e},cancellationToken:ct))).AsList();var ev=(await c.QueryAsync<CompraEventoDto>(new CommandDefinition("select 'PROCESSO' Tipo,numero||' — '||status Descricao,updated_at Data from sigov.compras_processo where tenant_id=@T and entidade_id=@E order by updated_at desc limit 10",new{T=t,E=e},cancellationToken:ct))).AsList();return new(r.Sol,r.Sem,r.Contr,r.Atas,r.Valor,ps,ev);}
 public async Task<IReadOnlyList<FornecedorDto>> FornecedoresAsync(long t,long e,CompraFiltro f,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<FornecedorDto>(new CommandDefinition("select id,nome,tipo_pessoa TipoPessoa,case when length(documento)<=4 then '***' else repeat('*',length(documento)-4)||right(documento,4) end DocumentoMascarado,email,telefone,endereco_resumido Endereco,status,observacoes from sigov.compras_fornecedor where tenant_id=@T and entidade_id=@E and (@S is null or status=@S) and (@B is null or nome ilike '%'||@B||'%') order by nome",new{T=t,E=e,S=N(f.Status),B=N(f.Busca)},cancellationToken:ct))).AsList();}
 public async Task<long> CriarFornecedorAsync(long t,long u,string corr,FornecedorInput i,CancellationToken ct){if(string.IsNullOrWhiteSpace(i.Nome)||string.IsNullOrWhiteSpace(i.Documento)||!new[]{"FISICA","JURIDICA"}.Contains(i.TipoPessoa))throw new ArgumentException("Nome, documento e tipo de pessoa válido são obrigatórios.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_fornecedor(tenant_id,entidade_id,nome,tipo_pessoa,documento,email,telefone,endereco_resumido,observacoes,created_by,updated_by) values(@T,@EntidadeId,@Nome,@TipoPessoa,@Documento,@Email,@Telefone,@Endereco,@Observacoes,@U,@U) returning id",new{T=t,U=u,i.EntidadeId,Nome=i.Nome.Trim(),i.TipoPessoa,Documento=Digits(i.Documento),Email=N(i.Email),Telefone=N(i.Telefone),Endereco=N(i.Endereco),Observacoes=N(i.Observacoes)},tx,cancellationToken:ct));await Audit(c,tx,t,i.EntidadeId,"FORNECEDOR",id,"CRIAR",null,i,u,corr,ct);await tx.CommitAsync(ct);log.LogInformation("Fornecedor {FornecedorId} criado no tenant {TenantId} e entidade {EntidadeId}",id,t,i.EntidadeId);return id;}catch(PostgresException x)when(x.SqlState==PostgresErrorCodes.UniqueViolation){throw new InvalidOperationException("Documento já cadastrado para esta entidade.",x);}}
 public async Task<byte[]> ExportarFornecedoresAsync(long t,long e,long u,string corr,CancellationToken ct){var x=await FornecedoresAsync(t,e,new(),ct);var b=new StringBuilder("Nome;Tipo;Documento;Status;Email\n");foreach(var i in x)b.AppendLine($"\"{i.Nome.Replace("\"","\"\"")}\";{i.TipoPessoa};{i.DocumentoMascarado};{i.Status};{i.Email}");await using var c=factory.CreateConnection();await Audit(c,null,t,e,"FORNECEDOR",0,"EXPORTAR",null,new{Quantidade=x.Count},u,corr,ct);return Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(b.ToString())).ToArray();}
 public async Task<IReadOnlyList<SolicitacaoDto>> SolicitacoesAsync(long t,long e,CompraFiltro f,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<SolicitacaoDto>(new CommandDefinition("select s.id,s.unidade_solicitante UnidadeSolicitante,s.justificativa,s.prioridade,s.origem,s.status,coalesce(sum(i.quantidade*i.valor_estimado),0) ValorEstimado,s.created_at CreatedAt from sigov.compras_solicitacao s left join sigov.compras_solicitacao_item i on i.solicitacao_id=s.id where s.tenant_id=@T and s.entidade_id=@E and (@S is null or s.status=@S) group by s.id order by s.created_at desc",new{T=t,E=e,S=N(f.Status)},cancellationToken:ct))).AsList();}
 public async Task<long> CriarSolicitacaoAsync(long t,long u,string corr,SolicitacaoInput i,CancellationToken ct){if(i.Itens.Count==0||i.Itens.Any(x=>x.Quantidade<=0||x.ValorEstimado<0)||string.IsNullOrWhiteSpace(i.Justificativa))throw new ArgumentException("Justificativa e itens com quantidades válidas são obrigatórios.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_solicitacao(tenant_id,entidade_id,unidade_solicitante,justificativa,prioridade,origem,origem_referencia,observacao,created_by,updated_by) values(@T,@EntidadeId,@UnidadeSolicitante,@Justificativa,@Prioridade,@Origem,@OrigemReferencia,@Observacao,@U,@U) returning id",new{T=t,U=u,i.EntidadeId,i.UnidadeSolicitante,i.Justificativa,i.Prioridade,i.Origem,i.OrigemReferencia,i.Observacao},tx,cancellationToken:ct));foreach(var x in i.Itens)await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_solicitacao_item(tenant_id,entidade_id,solicitacao_id,descricao,quantidade,unidade,tipo_material_servico,valor_estimado,gera_pendencia_patrimonial) values(@T,@E,@Id,@Descricao,@Quantidade,@Unidade,@Tipo,@ValorEstimado,@GeraPendenciaPatrimonial)",new{T=t,E=i.EntidadeId,Id=id,x.Descricao,x.Quantidade,x.Unidade,x.Tipo,x.ValorEstimado,x.GeraPendenciaPatrimonial},tx,cancellationToken:ct));await Audit(c,tx,t,i.EntidadeId,"SOLICITACAO",id,"CRIAR",null,i,u,corr,ct);await tx.CommitAsync(ct);return id;}
 public Task AlterarSolicitacaoAsync(long t,long e,long u,string corr,long id,string acao,string? just,CancellationToken ct)=>Tx(async(c,tx)=>{var atual=await c.ExecuteScalarAsync<string?>(new CommandDefinition("select status from sigov.compras_solicitacao where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=t,E=e,Id=id},tx,cancellationToken:ct))??throw new KeyNotFoundException();var novo=acao.ToLowerInvariant() switch{"enviar" when atual=="RASCUNHO"=>"ENVIADA","aprovar" when atual is "ENVIADA" or "EM_ANALISE"=>"APROVADA","rejeitar" when atual is "ENVIADA" or "EM_ANALISE"=>"REJEITADA",_=>throw new InvalidOperationException("Transição de solicitação inválida.")};if(novo=="REJEITADA"&&string.IsNullOrWhiteSpace(just))throw new ArgumentException("Justificativa é obrigatória.");await c.ExecuteAsync(new CommandDefinition("update sigov.compras_solicitacao set status=@N,updated_at=now(),updated_by=@U where id=@Id; insert into sigov.compras_solicitacao_historico(tenant_id,entidade_id,solicitacao_id,status_anterior,status_novo,justificativa,usuario_id,correlation_id) values(@T,@E,@Id,@A,@N,@J,@U,@C)",new{T=t,E=e,Id=id,A=atual,N=novo,J=N(just),U=u,C=corr},tx,cancellationToken:ct));await Audit(c,tx,t,e,"SOLICITACAO",id,"STATUS",new{Status=atual},new{Status=novo},u,corr,ct);},ct);
 public async Task<IReadOnlyList<ProcessoDto>> ProcessosAsync(long t,long e,CompraFiltro f,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<ProcessoDto>(new CommandDefinition("select p.id,p.numero,p.exercicio,m.nome Modalidade,j.nome Criterio,p.objeto,p.status,p.valor_estimado ValorEstimado,p.data_limite DataLimite from sigov.compras_processo p join sigov.compras_parametro_modalidade m on m.id=p.modalidade_id join sigov.compras_parametro_criterio j on j.id=p.criterio_id where p.tenant_id=@T and p.entidade_id=@E and (@S is null or p.status=@S) order by p.exercicio desc,p.numero",new{T=t,E=e,S=N(f.Status)},cancellationToken:ct))).AsList();}
 public async Task<ProcessoDetalhe?> ProcessoAsync(long t,long e,long id,CancellationToken ct){var p=(await ProcessosAsync(t,e,new(),ct)).SingleOrDefault(x=>x.Id==id);if(p is null)return null;await using var c=factory.CreateConnection();var itens=(await c.QueryAsync<CompraLinhaDto>(new CommandDefinition("select id,numero::text Numero,descricao Descricao,status,null Fornecedor,quantidade*valor_estimado Valor,null Inicio,null Fim from sigov.compras_processo_item where tenant_id=@T and entidade_id=@E and processo_id=@Id order by numero",new{T=t,E=e,Id=id},cancellationToken:ct))).AsList();var h=(await c.QueryAsync<CompraEventoDto>(new CommandDefinition("select 'FASE' Tipo,status_anterior||' → '||status_novo Descricao,ocorrido_em Data from sigov.compras_processo_fase_historico where tenant_id=@T and entidade_id=@E and processo_id=@Id order by ocorrido_em desc",new{T=t,E=e,Id=id},cancellationToken:ct))).AsList();return new(p,itens,h);}
 public async Task<long> CriarProcessoAsync(long t,long u,string corr,ProcessoInput i,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_processo(tenant_id,entidade_id,exercicio,numero,modalidade_id,criterio_id,objeto,justificativa,data_abertura,data_limite,solicitacao_id,valor_estimado,created_by,updated_by) select @T,@EntidadeId,@Exercicio,@Numero,m.id,j.id,@Objeto,@Justificativa,@DataAbertura,@DataLimite,@SolicitacaoId,coalesce((select sum(quantidade*valor_estimado) from sigov.compras_solicitacao_item where solicitacao_id=@SolicitacaoId),0),@U,@U from sigov.compras_parametro_modalidade m cross join sigov.compras_parametro_criterio j where m.codigo=@ModalidadeCodigo and j.codigo=@CriterioCodigo and m.ativo and j.ativo returning id",new{T=t,U=u,i.EntidadeId,i.Exercicio,i.Numero,i.ModalidadeCodigo,i.CriterioCodigo,i.Objeto,i.Justificativa,i.DataAbertura,i.DataLimite,i.SolicitacaoId},tx,cancellationToken:ct));if(id==0)throw new ArgumentException("Modalidade ou critério não encontrado no catálogo persistente.");if(i.SolicitacaoId is not null)await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_processo_item(tenant_id,entidade_id,processo_id,numero,descricao,quantidade,unidade,tipo_material_servico,valor_estimado,gera_pendencia_patrimonial) select tenant_id,entidade_id,@Id,row_number() over(order by id),descricao,quantidade,unidade,tipo_material_servico,valor_estimado,gera_pendencia_patrimonial from sigov.compras_solicitacao_item where solicitacao_id=@S; update sigov.compras_solicitacao set status='CONVERTIDA_EM_PROCESSO' where tenant_id=@T and entidade_id=@EntidadeId and id=@S",new{T=t,i.EntidadeId,Id=id,S=i.SolicitacaoId},tx,cancellationToken:ct));await Audit(c,tx,t,i.EntidadeId,"PROCESSO",id,"CRIAR",null,i,u,corr,ct);await tx.CommitAsync(ct);return id;}
 public Task AvancarAsync(long t,long e,long u,string corr,long id,string fase,CancellationToken ct)=>Tx(async(c,tx)=>{var a=await c.QuerySingleOrDefaultAsync<P>(new CommandDefinition("select status,objeto,data_abertura,data_limite from sigov.compras_processo where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=t,E=e,Id=id},tx,cancellationToken:ct))??throw new KeyNotFoundException();var ordem=new[]{"PLANEJAMENTO","PESQUISA_PRECO","EDITAL_TR","PUBLICADO","RECEBENDO_PROPOSTAS","JULGAMENTO","ADJUDICADO","HOMOLOGADO","CONTRATADO"};if(Array.IndexOf(ordem,fase)!=Array.IndexOf(ordem,a.Status)+1)throw new InvalidOperationException("A fase deve avançar uma etapa por vez.");if(fase=="PUBLICADO"&&(a.DataAbertura is null||a.DataLimite is null))throw new InvalidOperationException("Abertura e prazo são obrigatórios antes da publicação.");if(fase=="JULGAMENTO"&&await c.ExecuteScalarAsync<long>(new CommandDefinition("select count(*) from sigov.compras_cotacao q join sigov.compras_processo_item i on i.id=q.processo_item_id where i.processo_id=@Id",new{Id=id},tx,cancellationToken:ct))==0)throw new InvalidOperationException("É necessária ao menos uma cotação.");await Phase(c,tx,t,e,id,a.Status,fase,u,corr,ct);},ct);
 public async Task<long> CotarAsync(long t,long e,long u,string corr,long id,CotacaoInput i,CancellationToken ct){if(i.ValorUnitario<=0||i.Quantidade<=0)throw new ArgumentException("Valores da cotação devem ser positivos.");if(i.Status=="CLASSIFICADA"&&i.Validade<DateOnly.FromDateTime(DateTime.UtcNow))throw new InvalidOperationException("Proposta vencida não pode ser classificada.");if(i.Status=="DESCLASSIFICADA"&&string.IsNullOrWhiteSpace(i.JustificativaDesclassificacao))throw new ArgumentException("Justificativa de desclassificação é obrigatória.");await using var c=factory.CreateConnection();var idq=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_cotacao(tenant_id,entidade_id,processo_id,processo_item_id,fornecedor_id,valor_unitario,quantidade,prazo_entrega_dias,validade,observacao,status,justificativa_desclassificacao,created_by) select @T,@E,@P,@I,@F,@V,@Q,@Prazo,@Validade,@Obs,@S,@J,@U where exists(select 1 from sigov.compras_processo_item where id=@I and processo_id=@P and tenant_id=@T and entidade_id=@E) returning id",new{T=t,E=e,P=id,I=i.ProcessoItemId,F=i.FornecedorId,V=i.ValorUnitario,Q=i.Quantidade,Prazo=i.PrazoEntregaDias,i.Validade,Obs=N(i.Observacao),S=i.Status,J=N(i.JustificativaDesclassificacao),U=u},cancellationToken:ct));if(idq==0)throw new KeyNotFoundException();return idq;}
 public Task JulgarAsync(long t,long e,long u,string corr,long id,JulgmentoInputCompat i,CancellationToken ct)=>Tx(async(c,tx)=>{var s=await c.ExecuteScalarAsync<string?>(new CommandDefinition("select status from sigov.compras_processo where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=t,E=e,Id=id},tx,cancellationToken:ct));if(s!="JULGAMENTO")throw new InvalidOperationException("Somente processos em JULGAMENTO podem ser julgados.");var q=await c.QuerySingleOrDefaultAsync<Q>(new CommandDefinition("select q.fornecedor_id FornecedorId,q.valor_unitario*q.quantidade Valor,q.validade,q.status from sigov.compras_cotacao q where q.id=@Q and q.processo_id=@P and q.processo_item_id=@I",new{Q=i.CotacaoId,P=id,I=i.ProcessoItemId},tx,cancellationToken:ct))??throw new KeyNotFoundException();if(q.Validade<DateOnly.FromDateTime(DateTime.UtcNow)||q.Status=="DESCLASSIFICADA")throw new InvalidOperationException("Cotação vencida ou desclassificada.");await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_julgamento(tenant_id,entidade_id,processo_id,processo_item_id,cotacao_id,fornecedor_id,valor_final,status,justificativa,usuario_id) values(@T,@E,@P,@I,@Q,@F,@V,@S,@J,@U) on conflict(processo_item_id) do update set cotacao_id=excluded.cotacao_id,fornecedor_id=excluded.fornecedor_id,valor_final=excluded.valor_final,status=excluded.status,justificativa=excluded.justificativa,usuario_id=excluded.usuario_id,julgado_em=now(); update sigov.compras_processo_item set status=@S where id=@I",new{T=t,E=e,P=id,I=i.ProcessoItemId,Q=i.CotacaoId,F=q.FornecedorId,V=q.Valor,S=i.Status,J=i.Justificativa,U=u},tx,cancellationToken:ct));await Audit(c,tx,t,e,"JULGAMENTO",i.ProcessoItemId,"JULGAR",null,i,u,corr,ct);},ct);
 public Task HomologarAsync(long t,long e,long u,string corr,long id,CancellationToken ct)=>Tx(async(c,tx)=>{var s=await c.ExecuteScalarAsync<string?>(new CommandDefinition("select status from sigov.compras_processo where tenant_id=@T and entidade_id=@E and id=@Id for update",new{T=t,E=e,Id=id},tx,cancellationToken:ct));if(s is not("JULGAMENTO" or "ADJUDICADO"))throw new InvalidOperationException("Processo não está apto à homologação.");if(await c.ExecuteScalarAsync<long>(new CommandDefinition("select count(*) from sigov.compras_processo_item where processo_id=@Id and status not in('JULGADO','FRACASSADO')",new{Id=id},tx,cancellationToken:ct))>0)throw new InvalidOperationException("Todos os itens devem estar julgados ou fracassados.");await Phase(c,tx,t,e,id,s,"HOMOLOGADO",u,corr,ct);},ct);
 public Task<IReadOnlyList<CompraLinhaDto>> ContratosAsync(long t,long e,CompraFiltro f,CancellationToken ct)=>Lines("compras_contrato",t,e,f,ct); public Task<IReadOnlyList<CompraLinhaDto>> AtasAsync(long t,long e,CompraFiltro f,CancellationToken ct)=>Lines("compras_ata_registro_preco",t,e,f,ct);
 public async Task<long> CriarContratoAsync(long t,long u,string corr,ContratoInput i,CancellationToken ct){if(i.Fim<=i.Inicio)throw new ArgumentException("Fim da vigência deve ser posterior ao início.");return await CriarInstrumento("compras_contrato",t,u,corr,i.EntidadeId,i.ProcessoId,i.FornecedorId,i.Numero,i.Objeto,i.Valor,i.Inicio,i.Fim,i.Gestor,i.Fiscal,i.Observacoes,ct);}
 public Task<long> CriarAtaAsync(long t,long u,string corr,AtaInput i,CancellationToken ct){if(i.Fim<=i.Inicio)throw new ArgumentException("Fim da vigência deve ser posterior ao início.");return CriarInstrumento("compras_ata_registro_preco",t,u,corr,i.EntidadeId,i.ProcessoId,i.FornecedorId,i.Numero,i.Objeto,i.ValorGlobal,i.Inicio,i.Fim,null,null,null,ct);}
 async Task<long> CriarInstrumento(string table,long t,long u,string corr,long e,long p,long f,string n,string o,decimal v,DateOnly ini,DateOnly fim,string? gestor,string? fiscal,string? obs,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var ok=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.compras_processo p join sigov.compras_fornecedor f on f.id=@F and f.tenant_id=p.tenant_id and f.entidade_id=p.entidade_id where p.id=@P and p.tenant_id=@T and p.entidade_id=@E and p.status='HOMOLOGADO' and f.status='ATIVO')",new{T=t,E=e,P=p,F=f},tx,cancellationToken:ct));if(!ok)throw new InvalidOperationException("Processo deve estar homologado e fornecedor ativo.");var sql=table=="compras_contrato"?$"insert into sigov.{table}(tenant_id,entidade_id,processo_id,fornecedor_id,numero,objeto,valor_contratado,data_inicio,data_fim,gestor,fiscal,observacoes,created_by,updated_by) values(@T,@E,@P,@F,@N,@O,@V,@Ini,@Fim,@Gestor,@Fiscal,@Obs,@U,@U) returning id":$"insert into sigov.{table}(tenant_id,entidade_id,processo_id,fornecedor_id,numero,objeto,valor_global,data_inicio,data_fim,created_by,updated_by) values(@T,@E,@P,@F,@N,@O,@V,@Ini,@Fim,@U,@U) returning id";var id=await c.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{T=t,E=e,P=p,F=f,N=n,O=o,V=v,Ini=ini,Fim=fim,Gestor=N(gestor),Fiscal=N(fiscal),Obs=N(obs),U=u},tx,cancellationToken:ct));await Audit(c,tx,t,e,table,id,"CRIAR",null,new{p,f,n,v,ini,fim},u,corr,ct);await tx.CommitAsync(ct);return id;}
 async Task<IReadOnlyList<CompraLinhaDto>> Lines(string table,long t,long e,CompraFiltro f,CancellationToken ct){var valor=table=="compras_contrato"?"valor_contratado":"valor_global";await using var c=factory.CreateConnection();return(await c.QueryAsync<CompraLinhaDto>(new CommandDefinition($"select x.id,x.numero,x.objeto Descricao,x.status,f.nome Fornecedor,x.{valor} Valor,x.data_inicio Inicio,x.data_fim Fim from sigov.{table} x join sigov.compras_fornecedor f on f.id=x.fornecedor_id where x.tenant_id=@T and x.entidade_id=@E and (@S is null or x.status=@S) and (@F is null or x.fornecedor_id=@F) order by x.data_fim",new{T=t,E=e,S=N(f.Status),F=f.FornecedorId},cancellationToken:ct))).AsList();}
 async Task Phase(NpgsqlConnection c,NpgsqlTransaction tx,long t,long e,long id,string a,string n,long u,string corr,CancellationToken ct){await c.ExecuteAsync(new CommandDefinition("update sigov.compras_processo set status=@N,updated_at=now(),updated_by=@U where id=@Id;insert into sigov.compras_processo_fase_historico(tenant_id,entidade_id,processo_id,status_anterior,status_novo,usuario_id,correlation_id) values(@T,@E,@Id,@A,@N,@U,@C)",new{T=t,E=e,Id=id,A=a,N=n,U=u,C=corr},tx,cancellationToken:ct));await Audit(c,tx,t,e,"PROCESSO",id,"FASE",new{Status=a},new{Status=n},u,corr,ct);}
 async Task Tx(Func<NpgsqlConnection,NpgsqlTransaction,Task> fn,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await fn(c,tx);await tx.CommitAsync(ct);}
 static Task Audit(NpgsqlConnection c,NpgsqlTransaction? tx,long t,long e,string ent,long id,string op,object? antes,object? depois,long u,string corr,CancellationToken ct)=>c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_auditoria(tenant_id,entidade_id,entidade,registro_id,operacao,antes,depois,usuario_id,correlation_id) values(@T,@E,@Ent,@Id,@Op,cast(@Antes as jsonb),cast(@Depois as jsonb),@U,@C)",new{T=t,E=e,Ent=ent,Id=id,Op=op,Antes=antes is null?null:JsonSerializer.Serialize(antes),Depois=depois is null?null:JsonSerializer.Serialize(depois),U=u,C=corr},tx,cancellationToken:ct));
 static string? N(string? s)=>string.IsNullOrWhiteSpace(s)?null:s.Trim();static string Digits(string s)=>new(s.Where(char.IsDigit).ToArray());sealed record R(long Sol,long Sem,long Contr,long Atas,decimal Valor);sealed record P(string Status,string Objeto,DateOnly? DataAbertura,DateOnly? DataLimite);sealed record Q(long FornecedorId,decimal Valor,DateOnly Validade,string Status);
}
